export function getGermanHardTubeSelectionText(value: string) {
  const { key, tokens } = canonicalFittingDetailText(value);
  const copy = germanMessages[key];
  if (!copy) return fittingDetailText(value, "en");
  const leading = value.match(/^\s*/)?.[0] ?? "";
  const trailing = value.match(/\s*$/)?.[0] ?? "";
  return leading + copy.replace(/\{(\d+)\}/g, (_match, index: string) => tokens[Number(index)]) + trailing;
}
